class Solution {
public:
    string longestPrefix(string s) {
        int n = s.size();
        vector<int> lps(n, 0);
        int prev = 0, i = 1;
        while (i < n) {
            if (s[i] == s[prev]) {
                lps[i++] = ++prev;
            } else if (prev > 0) {
                prev = lps[prev - 1];
            } else {
                lps[i++] = 0;
            }
        }
        return s.substr(0, lps.back());
    }
};

class Solution {
    public String longestPrefix(String s) {
        int n = s.length();
        int[] lps = new int[n];
        int prev = 0, i = 1;
        while (i < n) {
            if (s.charAt(i) == s.charAt(prev)) {
                lps[i++] = ++prev;
            } else if (prev > 0) {
                prev = lps[prev - 1];
            } else {
                lps[i++] = 0;
            }
        }
        return s.substring(0, lps[n - 1]);
    }
}

var longestPrefix = function(s) {
    const n = s.length;
    const lps = new Int32Array(n);
    let prev = 0, i = 1;
    while (i < n) {
        if (s[i] === s[prev]) {
            lps[i++] = ++prev;
        } else if (prev > 0) {
            prev = lps[prev - 1];
        } else {
            lps[i++] = 0;
        }
    }
    return s.slice(0, lps[n - 1]);
};
